    <div className={'ieq-editing-status '+(editable?'editable':'readonly')} role="status"><strong>{editable?'可编辑':'只读'}</strong><span>{editingReason}</span>{historical&&<Button size="sm" variant="outline" disabled={busy} onClick={()=>void load(draft.id)}>返回当前版本继续</Button>}{!historical&&draft.canRevise&&<Button size="sm" variant="outline" disabled={busy||quoteWorkDirty} onClick={()=>void act('ie-quote-revise',{id:draft.id,version:draft.version},'已创建修订草稿，原释放版本仍保留。')}>创建修订草稿继续填写</Button>}</div>
    {draft.submissionBlockReason&&<div role="alert" className="ieq-alert warning">{draft.submissionBlockReason}</div>}
