    <div className="ieq-product-tabs" aria-label="报价款色与数量档">{draft.lines.map((item,i)=><button key={item.id} className={item.id===line?.id?'active':''} onClick={()=>setLineId(item.id)}>{item.model||`产品 ${i+1}`}{item.color?' · '+item.color:''}<small>{number(item.quantityMin)===null?'数量待定':item.quantityMin}{item.quantityMax?'–'+item.quantityMax:''} 副</small></button>)}{editable&&<Button variant="outline" onClick={()=>{const item=newLine(index.materialChecklist||[]);patch({lines:[...draft.lines,item]});setLineId(item.id);}}>＋ 添加款色 / 数量档</Button>}</div>
